SELECT 
FROM workflow_run
WHERE workflow_definition_id = #{workflowDefinitionId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM workflow_run
WHERE workflow_definition_id = #{workflowDefinitionId}

mapper.update:
UPDATE workflow_run
SET status = #{toStatus},
    error_code = #{errorCode},
    error_summary = #{errorSummary},
    finished_at = #{finishedAt},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = #{fromStatus}

UPDATE workflow_run
SET status = 'RUNNING',
    started_at = #{startedAt},
    updated_at = #{startedAt}
WHERE id = #{id}
  AND status = 'QUEUED'

UPDATE workflow_run
SET current_node_key = #{currentNodeKey},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'RUNNING'
